export function shortestPath(
    graph: Map<string, string[]>,
    start: string,
    goal: string,
): string[] | null {
    const queue = [start];
    const parent = new Map<string, string>();

    while (queue.length > 0) {
        // TODO: dequeue in FIFO order, skip visited nodes, and record parents
        const node = queue.pop() as string;
        if (node === goal) {
            return rebuild(parent, start, goal);
        }
        for (const next of graph.get(node) ?? []) {
            parent.set(next, node);
            queue.push(next);
        }
    }

    return null;
}

function rebuild(
    parent: Map<string, string>,
    start: string,
    goal: string,
): string[] {
    const path = [goal];
    let current = goal;
    while (current !== start) {
        const previous = parent.get(current);
        if (previous === undefined) {
            return [];
        }
        path.push(previous);
        current = previous;
    }
    return path.reverse();
}

